import React, { useState, useEffect, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import SvgFlow from '../components/SvgFlow';
import { parseToGraph, codeTemplates } from '../utils/parseToGraph';

function Editor() {
  const [searchParams] = useSearchParams();
  const [code, setCode] = useState('');
  const [lang, setLang] = useState('python');
  const [graph, setGraph] = useState(null);
  const [message, setMessage] = useState('');
  const [highlightedLine, setHighlightedLine] = useState(null);
  const [selectedNode, setSelectedNode] = useState(null);
  const textareaRef = useRef(null);

  useEffect(() => {
    const langParam = searchParams.get('lang');
    if (langParam && codeTemplates[langParam]) {
      setLang(langParam);
      setCode(codeTemplates[langParam]);
    }
  }, [searchParams]);

  useEffect(() => {
    console.log("selectedNode state changed:", selectedNode);
  }, [selectedNode]);

  const handleGenerate = () => {
    if (!code.trim()) {
      setMessage('Please enter some code to generate a flowchart.');
      setGraph(null);
      return;
    }
    
    // Validate if code matches selected language
    const isValidLanguage = validateLanguage(code, lang);
    if (!isValidLanguage) {
      setMessage(`The code you entered doesn't match the selected language (${lang.toUpperCase()}). Please select the correct language or update your code.`);
      setGraph(null);
      return;
    }
    
    const g = parseToGraph(code);
    console.log("Generated graph:", g);
    console.log("First node:", g.nodes[0]);
    console.log("Node with lineNumber?", g.nodes.map(n => ({ id: n.id, text: n.text, lineNumber: n.lineNumber })));
    setGraph(g);
    setMessage('');
  };

  const validateLanguage = (code, selectedLang) => {
    const trimmedCode = code.trim();
    const lowerCode = code.toLowerCase();
    
    switch(selectedLang) {
      case 'python':
        // Check for Python-specific syntax
        const hasPythonSyntax = /def\s+\w+|class\s+\w+|import\s+\w+|from\s+\w+\s+import|for\s+\w+\s+in\s+|if\s+.*:|elif\s+.*:|while\s+.*:|print\(|range\(/.test(trimmedCode);
        const hasNonPythonSyntax = /\bfunction\b|\bconst\b|\blet\b|\bvar\b|console\.log|#include|System\.out\.println|<html|SELECT\s+.*\s+FROM/i.test(trimmedCode);
        return hasPythonSyntax && !hasNonPythonSyntax;
      
      case 'javascript':
        // Check for JavaScript-specific syntax
        const hasJSSyntax = /function\s+\w+|const\s+\w+|let\s+\w+|var\s+\w+|console\.log|=>|\.forEach|\.map|\.filter/.test(trimmedCode);
        const hasNonJSSyntax = /^def\s+\w+|#include|System\.out\.println|<html|SELECT\s+.*\s+FROM/i.test(trimmedCode);
        return hasJSSyntax && !hasNonJSSyntax;
      
      case 'java':
        // Check for Java-specific syntax
        const hasJavaSyntax = /class\s+\w+|public\s+(static\s+)?void|private\s+|protected\s+|System\.out\.println|import\s+java|public\s+class/.test(trimmedCode);
        const hasNonJavaSyntax = /^def\s+\w+|#include|console\.log|<html|SELECT\s+.*\s+FROM|cout\s*<</i.test(trimmedCode);
        return hasJavaSyntax && !hasNonJavaSyntax;
      
      case 'c':
        // Check for C-specific syntax
        const hasCSyntax = /#include\s*<|int\s+main|printf\(|scanf\(|void\s+\w+\(|return\s+0;|stdio\.h/.test(trimmedCode);
        const hasNonCSyntax = /^def\s+\w+|console\.log|System\.out\.println|<html|SELECT\s+.*\s+FROM|cout\s*<<|using\s+namespace/i.test(trimmedCode);
        return hasCSyntax && !hasNonCSyntax;
      
      case 'cpp':
        // Check for C++-specific syntax
        const hasCppSyntax = /#include\s*<|using\s+namespace|cout\s*<<|cin\s*>>|std::|iostream|int\s+main/.test(trimmedCode);
        const hasNonCppSyntax = /^def\s+\w+|console\.log|System\.out\.println|<html|SELECT\s+.*\s+FROM|printf\(/i.test(trimmedCode);
        return hasCppSyntax && !hasNonCppSyntax;
      
      case 'sql':
        // Check for SQL-specific syntax
        const hasSQLSyntax = /\b(SELECT|INSERT|UPDATE|DELETE|FROM|WHERE|CREATE|DROP|ALTER|TABLE|DATABASE|JOIN|GROUP\s+BY|ORDER\s+BY)\b/i.test(trimmedCode);
        const hasNonSQLSyntax = /^def\s+\w+|function\s+\w+|#include|System\.out\.println|<html|console\.log|cout\s*<</i.test(trimmedCode);
        return hasSQLSyntax && !hasNonSQLSyntax;
      
      case 'html':
        // Check for HTML-specific syntax
        const hasHTMLSyntax = /<(!DOCTYPE\s+)?html|<head|<body|<div|<p|<h[1-6]|<style|<script|<title|<meta/i.test(trimmedCode);
        const hasNonHTMLSyntax = /^def\s+\w+|function\s+\w+(?!\s*\()|#include|System\.out\.println|SELECT\s+.*\s+FROM|console\.log(?!.*<)/i.test(trimmedCode);
        return hasHTMLSyntax && !hasNonHTMLSyntax;
      
      default:
        return true;
    }
  };

  const handleNodeClick = (lineNumber, node) => {
    console.log("handleNodeClick called with:", { lineNumber, node });
    
    if (!textareaRef.current) return;
    
    // Set the highlighted line
    setHighlightedLine(lineNumber);
    
    // Set the selected node for explanation
    setSelectedNode(node);
    console.log("Selected node set to:", node);
    
    // Scroll to the line in the textarea
    const lines = code.split('\n');
    const linesBefore = lines.slice(0, lineNumber - 1).join('\n');
    const charPosition = linesBefore.length + (lineNumber > 1 ? 1 : 0);
    
    // Move cursor to the line
    textareaRef.current.focus();
    textareaRef.current.setSelectionRange(charPosition, charPosition + lines[lineNumber - 1]?.length || 0);
    
    // Clear highlight after 2 seconds
    setTimeout(() => {
      setHighlightedLine(null);
    }, 2000);
  };

  const getNodeExplanation = (node) => {
    if (!node) return '';
    
    const nodeType = node.type || node.shape;
    const nodeText = node.text || node.label || '';
    
    let explanation = '';
    
    switch(nodeType) {
      case 'start':
      case 'terminal':
        if (nodeText.toLowerCase().includes('start')) {
          explanation = '🟢 **Program Start**\n\nThis is where your program begins. Every program needs a starting point, and this is it! All the instructions below this will be executed one by one.';
        } else if (nodeText.toLowerCase().includes('end')) {
          explanation = '🔴 **Program End**\n\nThis is where your program stops. Once the program reaches this point, it completes its task and finishes running.';
        }
        break;
      
      case 'input':
        explanation = `🔵 **Getting Input**\n\nThe program is receiving information here.\n\n**What it does:** ${nodeText}\n\nThink of this as the program asking for something it needs - like getting a number from the user, reading a file, or receiving function parameters.`;
        break;
      
      case 'output':
        explanation = `📤 **Showing Output**\n\nThe program is displaying or returning results here.\n\n**What it shows:** ${nodeText}\n\nThis is like the program telling you something - printing a message on screen, showing a result, or returning a value.`;
        break;
      
      case 'decision':
      case 'condition':
        explanation = `💎 **Making a Decision**\n\nThe program checks a condition and decides which path to take.\n\n**Question being asked:** ${nodeText}\n\n✅ If TRUE → follows the "Yes" arrow\n❌ If FALSE → follows the "No" arrow\n\nThis is like an "if statement" - the program chooses what to do based on whether something is true or false.`;
        break;
      
      case 'loop':
        explanation = `🔁 **Repeating (Loop)**\n\nThis creates a loop that repeats instructions multiple times.\n\n**Loop condition:** ${nodeText}\n\nThe code inside keeps running over and over as long as this condition is true. When it becomes false, the loop stops and the program continues.`;
        break;
      
      case 'process':
      case 'rectangle':
        if (nodeText.toLowerCase().includes('calculate') || nodeText.toLowerCase().includes('compute')) {
          explanation = `⚙️ **Doing Math**\n\n**Operation:** ${nodeText}\n\nThe program is performing a calculation here. It takes some numbers, does math with them, and usually stores the result to use later.`;
        } else if (nodeText.toLowerCase().includes('assign') || nodeText.toLowerCase().includes('set') || nodeText.includes('=')) {
          explanation = `📝 **Storing Information**\n\n**What's happening:** ${nodeText}\n\nThe program is saving a value in its memory (a variable). This is like putting something in a labeled box so you can find it and use it later.`;
        } else if (nodeText.toLowerCase().includes('call') || nodeText.toLowerCase().includes('function')) {
          explanation = `📞 **Calling a Function**\n\n**Function:** ${nodeText}\n\nThe program is running another piece of code (a function). It's like asking a helper to do a specific job, then coming back here when the helper is done.`;
        } else {
          explanation = `⚙️ **Processing**\n\n**Action:** ${nodeText}\n\nThe program is doing something here - performing an operation, transforming data, or executing an instruction.`;
        }
        break;
      
      case 'function':
        explanation = `🔧 **Function Definition**\n\n**Function name:** ${nodeText}\n\nThis defines a reusable block of code. You can "call" this function from anywhere in your program to run the code inside it. It's like creating a recipe you can follow multiple times.`;
        break;
      
      default:
        explanation = `📋 **Step**\n\n${nodeText}`;
        break;
    }
    
    // Add line number info
    if (node.lineNumber) {
      explanation += `\n\n📍 **Code Location:** Line ${node.lineNumber}`;
    }
    
    return explanation;
  };

  return (
    <main style={styles.container}>
      <div style={styles.splitContainer}>
        {/* Left side - Code Editor */}
        <section style={styles.leftPanel}>
          <div style={styles.controls}>
            <select 
              value={lang} 
              onChange={(e) => {
                const newLang = e.target.value;
                setLang(newLang);
                setCode(codeTemplates[newLang]);
              }} 
              style={styles.select}
            >
              <option value="python">Python</option>
              <option value="javascript">JavaScript</option>
              <option value="java">Java</option>
              <option value="c">C</option>
              <option value="cpp">C++</option>
              <option value="sql">SQL</option>
              <option value="html">HTML/CSS</option>
            </select>

            <button onClick={handleGenerate} style={styles.button}>
              Generate Flowchart
            </button>
          </div>

          <textarea
            ref={textareaRef}
            value={code}
            onChange={(e) => setCode(e.target.value)}
            style={styles.textarea}
            placeholder="Paste your code here..."
          />

          {message && <div style={styles.message}>{message}</div>}
        </section>

        {/* Right side - Flowchart */}
        <section style={styles.rightPanel}>
          <h3 style={styles.flowchartTitle}>Flowchart {selectedNode && "& Explanation"}</h3>
          <div style={styles.flowchartContainer}>
            {graph ? (
              <div style={{ 
                display: 'flex', 
                gap: '20px', 
                height: '100%', 
                width: '100%',
                minWidth: 0,
                overflow: 'hidden'
              }}>
                {/* Flowchart Section */}
                <div style={{ 
                  flex: selectedNode ? '0 0 50%' : '1', 
                  minHeight: 0,
                  minWidth: 0,
                  overflow: 'auto',
                  border: '2px solid #e5e7eb',
                  borderRadius: '8px',
                  background: '#ffffff',
                  padding: '10px'
                }}>
                  <SvgFlow graph={graph} onNodeClick={handleNodeClick} />
                </div>
                
                {/* Explanation Panel */}
                {selectedNode && (
                  <div style={{
                    flex: '0 0 48%',
                    minWidth: 0,
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    border: '3px solid #5a67d8',
                    borderRadius: '12px',
                    padding: '20px',
                    display: 'flex',
                    flexDirection: 'column',
                    overflow: 'hidden',
                    boxShadow: '0 10px 25px rgba(0,0,0,0.15)'
                  }}>
                    <div style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      marginBottom: '16px',
                      paddingBottom: '16px',
                      borderBottom: '2px solid rgba(255,255,255,0.3)',
                      flexShrink: 0
                    }}>
                      <h4 style={{
                        margin: 0,
                        fontSize: '18px',
                        fontWeight: 700,
                        color: '#ffffff',
                        textShadow: '0 2px 4px rgba(0,0,0,0.2)'
                      }}>💡 Step Explanation</h4>
                      <button 
                        onClick={() => {
                          console.log("Close button clicked");
                          setSelectedNode(null);
                        }} 
                        style={{
                          background: '#ffffff',
                          color: '#667eea',
                          border: 'none',
                          fontSize: '20px',
                          cursor: 'pointer',
                          padding: '6px 12px',
                          borderRadius: '6px',
                          fontWeight: 'bold',
                          transition: 'all 0.2s ease',
                          boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
                          flexShrink: 0
                        }}
                        onMouseOver={(e) => e.target.style.transform = 'scale(1.1)'}
                        onMouseOut={(e) => e.target.style.transform = 'scale(1)'}
                      >
                        ✕
                      </button>
                    </div>
                    <div style={{
                      flex: 1,
                      minHeight: 0,
                      overflowY: 'auto',
                      background: 'rgba(255,255,255,0.95)',
                      borderRadius: '8px',
                      padding: '16px'
                    }}>
                      {getNodeExplanation(selectedNode).split('\n\n').map((paragraph, idx) => (
                        <div key={idx} style={{
                          marginBottom: '16px',
                          fontSize: '15px',
                          lineHeight: 1.7,
                          color: '#1f2937',
                          fontWeight: paragraph.includes('**') ? '600' : '400'
                        }}>
                          {paragraph.split('**').map((part, i) => 
                            i % 2 === 1 ? (
                              <strong key={i} style={{ color: '#5a67d8', fontWeight: '700' }}>{part}</strong>
                            ) : (
                              <span key={i}>{part}</span>
                            )
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div style={styles.placeholder}>
                No flowchart yet — click "Generate Flowchart"
              </div>
            )}
          </div>
        </section>
      </div>
    </main>
  );
}

const styles = {
  container: {
    maxWidth: '100%',
    margin: '24px auto',
    padding: '0 24px',
    height: 'calc(100vh - 100px)'
  },
  splitContainer: {
    display: 'flex',
    gap: 20,
    height: '100%'
  },
  leftPanel: {
    flex: '0 0 38%',
    background: '#fff',
    padding: 20,
    borderRadius: 12,
    boxShadow: '0 6px 18px rgba(2,6,23,0.06)',
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden'
  },
  rightPanel: {
    flex: '1',
    background: '#fff',
    padding: 20,
    borderRadius: 12,
    boxShadow: '0 6px 18px rgba(2,6,23,0.06)',
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden',
    minWidth: 0
  },
  controls: {
    display: 'flex',
    gap: 12,
    alignItems: 'center',
    marginBottom: 12,
    flexShrink: 0
  },
  select: {
    padding: '8px 10px',
    borderRadius: 8,
    border: '1px solid #e6e9ef',
    fontSize: 14,
    cursor: 'pointer'
  },
  button: {
    padding: '8px 14px',
    background: '#4b0082',
    color: '#fff',
    border: 'none',
    borderRadius: 8,
    cursor: 'pointer',
    transition: 'all .2s ease',
    boxShadow: '0 6px 12px rgba(75,0,130,0.08)',
    fontSize: 14,
    fontWeight: 600
  },
  textarea: {
    width: '100%',
    flex: 1,
    padding: 12,
    borderRadius: 10,
    border: '1px solid #e6e9ef',
    fontFamily: 'monospace',
    fontSize: 13,
    resize: 'none',
    outline: 'none',
    transition: 'border-color .2s ease'
  },
  flowchartTitle: {
    margin: '0 0 16px 0',
    fontSize: 18,
    fontWeight: 600,
    color: '#1f2937',
    flexShrink: 0
  },
  flowchartContainer: {
    flex: 1,
    minHeight: 0,
    display: 'flex',
    flexDirection: 'column'
  },
  message: {
    marginTop: 10,
    padding: '12px 16px',
    borderRadius: 8,
    backgroundColor: '#fee2e2',
    color: '#991b1b',
    border: '1px solid #fca5a5',
    fontSize: '14px',
    fontWeight: '500',
    flexShrink: 0
  },
  placeholder: {
    color: '#9ca3af',
    padding: 40,
    textAlign: 'center',
    fontSize: 15
  },
  explanationPanel: {
    flex: '0 0 38%',
    background: '#f8fafc',
    border: '2px solid #e2e8f0',
    borderRadius: 12,
    padding: 16,
    display: 'flex',
    flexDirection: 'column',
    overflow: 'hidden',
    boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
    animation: 'slideIn 0.3s ease'
  },
  explanationHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 12,
    paddingBottom: 12,
    borderBottom: '2px solid #e2e8f0'
  },
  explanationTitle: {
    margin: 0,
    fontSize: 16,
    fontWeight: 700,
    color: '#1f2937'
  },
  closeButton: {
    background: 'transparent',
    border: 'none',
    fontSize: 20,
    color: '#6b7280',
    cursor: 'pointer',
    padding: '4px 8px',
    borderRadius: 4,
    transition: 'all 0.2s ease',
    fontWeight: 'bold'
  },
  explanationContent: {
    flex: 1,
    overflowY: 'auto',
    paddingRight: 8
  },
  explanationText: {
    margin: '0 0 12px 0',
    fontSize: 14,
    lineHeight: 1.6,
    color: '#374151',
    whiteSpace: 'pre-wrap'
  }
};

export default Editor;
